"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["3227"],{47460(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.cursor.direcao_invalida","status":422,"titulo":"Dire\xe7\xe3o de pagina\xe7\xe3o inv\xe1lida"},"descricao":{"codigo":"uniplus.cursor.direcao_invalida","requisitos":[],"oQueAconteceu":["O par\xe2metro **`direction`** da listagem paginada tem um valor diferente de\\n`next` ou `prev`.","Listagens paginadas por cursor navegam nos dois sentidos: `next` (padr\xe3o,\\navan\xe7a) e `prev` (retrocede). Quando `direction` n\xe3o \xe9 informado, o servidor\\nassume `next` \u2014 omitir o par\xe2metro nunca \xe9 a causa desta recusa. A recusa s\xf3\\nacontece quando o par\xe2metro est\xe1 presente com um valor que n\xe3o \xe9 nenhum dos\\ndois aceitos.","Um cursor emitido para uma dire\xe7\xe3o n\xe3o pode ser reaproveitado na outra\\ndire\xe7\xe3o \u2014 essa incompatibilidade \xe9 uma causa distinta, coberta por\\n[cursor inv\xe1lido](/erros/uniplus.cursor.invalido), e n\xe3o por esta p\xe1gina: aqui\\no problema est\xe1 no pr\xf3prio valor de `direction`, antes de qualquer cursor\\nentrar em jogo."],"comoResolver":["Informe `direction=next` ou `direction=prev` \u2014 compara\xe7\xe3o sem diferenciar\\nmai\xfasculas de min\xfasculas \u2014 ou omita o par\xe2metro para obter o comportamento\\npadr\xe3o (`next`, primeira p\xe1gina em diante)."],"ondeAparece":["Listagem paginada por cursor, quando o par\xe2metro direction est\xe1 presente"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Cursor"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);